using System.ComponentModel.DataAnnotations; using MaintenancePRO.Api.Models;
namespace MaintenancePRO.Api.Contracts;
public sealed record RegisterRequest([Required,EmailAddress,StringLength(254)]string Email,[Required,MinLength(12),StringLength(128)]string Password,[Required,StringLength(100)]string DisplayName);
public sealed record LoginRequest([Required,EmailAddress,StringLength(254)]string Email,[Required,StringLength(128)]string Password);
public sealed record AuthResponse(string AccessToken,DateTime ExpiresUtc,string Email,string DisplayName,string[] Roles);
public sealed record CreateEquipmentRequest([Required,StringLength(40)]string Code,[Required,StringLength(160)]string Name,[Required,StringLength(160)]string Location,[Required,StringLength(80)]string Category,string? Manufacturer,string? Model,string? SerialNumber,DateTime? CommissionedUtc,string? Notes);
public sealed record UpdateEquipmentRequest([Required,StringLength(160)]string Name,[Required,StringLength(160)]string Location,[Required,StringLength(80)]string Category,string? Manufacturer,string? Model,string? SerialNumber,DateTime? CommissionedUtc,string? Notes,EquipmentStatus Status);
public sealed record CreateBreakdownRequest([Range(1,int.MaxValue)]int EquipmentId,[Required,StringLength(160)]string Title,[Required,StringLength(3000)]string Description,BreakdownSeverity Severity);
public sealed record CreateDiagnosisRequest([Required,StringLength(3000)]string Findings,[StringLength(3000)]string? RootCause,[StringLength(3000)]string? RecommendedAction);
public sealed record DiagnosisDecisionRequest(DiagnosisStatus Status);
public sealed record CreateInterventionRequest([Range(1,int.MaxValue)]int BreakdownId,[Required,StringLength(160)]string Title,[Required,StringLength(3000)]string WorkDescription);
public sealed record UpdateInterventionRequest(InterventionStatus Status,[StringLength(3000)]string? Resolution,string? AssignedTechnicianId,decimal? LaborHours,decimal? Cost);
public sealed record SetAccountStatusRequest(AccountStatus Status); public sealed record SetRoleRequest([Required]string Role);
